 const opaque=o=>o.isMesh&&o.userData.role!=='printed-artwork'&&o.material.opacity!==0;
 const solids=[];frame.traverse(o=>{if(opaque(o)&&!attached.some(r=>under(o,r)))solids.push(o);});
